import { ISystem } from "../contracts/ISystem";
import { SystemPhase, InitPhase } from "../contracts/SystemPhase";
import { EcsWorld } from "../core/ecs/EcsWorld";
import { ComponentStore } from "../core/ecs/ComponentStore";
import { EntityId } from "../core/ecs/Entity";
import {
  TransformComponent,
  KinematicVelocityComponent,
  KinematicTargetComponent,
  TetherComponent,
  HealthComponent,
  InputIntentComponent,
  WeaverAIComponent,
  PlayerTag,
  WeaverTag,
  TraversalStateComponent,
  InvulnerabilityComponent,
  WeaverTraversalComponent
} from "../core/ecs/Components";
import { EntityRefs } from "../core/ecs/EntityRefs";
import { IVisualRegistry } from "../contracts/IVisualRegistry";
import { ARENA_CONFIG, GAMEPLAY_TUNING, VISUAL_JUICE_CONFIG } from "../core/engine/ArenaConfig";
import * as BABYLON from "@babylonjs/core";

export class EntitySpawnerSystem implements ISystem {
  readonly phase = SystemPhase.Intents;
  readonly initPhase = InitPhase.World;

  constructor(
    private refs: EntityRefs,
    private entities: EcsWorld,
    private transforms: ComponentStore<TransformComponent>,
    private velocities: ComponentStore<KinematicVelocityComponent>,
    private targets: ComponentStore<KinematicTargetComponent>,
    private tethers: ComponentStore<TetherComponent>,
    private healths: ComponentStore<HealthComponent>,
    private inputs: ComponentStore<InputIntentComponent>,
    private weaverAIs: ComponentStore<WeaverAIComponent>,
    private playerTags: ComponentStore<PlayerTag>,
    private weaverTags: ComponentStore<WeaverTag>,
    private visualRegistry: IVisualRegistry,
    private traversal: ComponentStore<TraversalStateComponent>,
    private iframes: ComponentStore<InvulnerabilityComponent>,
    private weaverTraversal: ComponentStore<WeaverTraversalComponent>
  ) {}

  public init(): void {
    this.spawnWeaver();
    this.spawnPlayer();
  }

  public spawnWeaver(existingId?: EntityId): EntityId {
    const scene = this.visualRegistry.getScene();
    if (!scene) return -1;

    const weaverId = existingId ?? this.entities.create();
    this.entities.clearEntityComponents(weaverId);

    this.visualRegistry.unregisterTransformNode(weaverId);

    this.transforms.add(weaverId, {
      x: 0,
      y: ARENA_CONFIG.VERTICAL.WEAVER_SPAWN_Y,
      z: 0,
      qx: 0,
      qy: 0,
      qz: 0,
      qw: 1,
      prevX: 0,
      prevY: ARENA_CONFIG.VERTICAL.WEAVER_SPAWN_Y - 6.0,
      prevZ: 0,
      prevQx: 0,
      prevQy: 0,
      prevQz: 0,
      prevQw: 1
    });
    this.velocities.add(weaverId, { x: 4.5, y: 0, z: 0 });
    this.targets.add(weaverId, { x: 0, y: ARENA_CONFIG.VERTICAL.WEAVER_SPAWN_Y, z: 0, active: true });
    this.weaverAIs.add(weaverId, {
      state: "SWEEPING",
      timeInState: 0,
      hue: String.fromCharCode(35) + VISUAL_JUICE_CONFIG.WEAVER_COLORS.SWEEPING,
      scrollSpeed: ARENA_CONFIG.SCROLL_SPEED.BASE
    });
    this.healths.add(weaverId, { current: 100, max: 100 });
    this.weaverTags.add(weaverId, {});
    this.weaverTraversal.add(weaverId, {
      velX: 4.5,
      velY: 0,
      isGrounded: false,
      isWallClinging: false,
      wallNormalX: 0
    });
    this.refs.weaver = weaverId;

    const wMesh = BABYLON.MeshBuilder.CreateIcoSphere(
      "weaverVisual",
      { radius: ARENA_CONFIG.ENTITY.WEAVER_RADIUS, subdivisions: 3 },
      scene
    );
    const wMat = new BABYLON.PBRMaterial("weaverMat", scene);
    wMat.albedoColor = new BABYLON.Color3(0.15, 0.15, 0.18);
    wMat.metallic = VISUAL_JUICE_CONFIG.MATERIALS.WEAVER.METALLIC;
    wMat.roughness = VISUAL_JUICE_CONFIG.MATERIALS.WEAVER.ROUGHNESS;
    wMat.clearCoat.isEnabled = true;
    wMat.clearCoat.intensity = VISUAL_JUICE_CONFIG.MATERIALS.WEAVER.CLEAR_COAT_INTENSITY;
    wMat.clearCoat.roughness = VISUAL_JUICE_CONFIG.MATERIALS.WEAVER.CLEAR_COAT_ROUGHNESS;
    wMesh.material = wMat;
    this.visualRegistry.registerTransformNode(weaverId, wMesh);

    return weaverId;
  }

  public spawnPlayer(existingId?: EntityId): EntityId {
    const scene = this.visualRegistry.getScene();
    if (!scene) return -1;

    const playerId = existingId ?? this.entities.create();
    this.entities.clearEntityComponents(playerId);

    this.visualRegistry.unregisterTransformNode(playerId);

    this.transforms.add(playerId, {
      x: 0,
      y: ARENA_CONFIG.VERTICAL.PLAYER_SPAWN_Y,
      z: 0,
      qx: 0,
      qy: 0,
      qz: 0,
      qw: 1,
      prevX: 0,
      prevY: ARENA_CONFIG.VERTICAL.PLAYER_SPAWN_Y,
      prevZ: 0,
      prevQx: 0,
      prevQy: 0,
      prevQz: 0,
      prevQw: 1
    });
    this.velocities.add(playerId, { x: 0, y: 0, z: 0 });
    this.targets.add(playerId, { x: 0, y: ARENA_CONFIG.VERTICAL.PLAYER_SPAWN_Y, z: 0, active: true });
    this.tethers.add(playerId, {
      anchorX: 0,
      anchorY: ARENA_CONFIG.VERTICAL.WEAVER_SPAWN_Y,
      anchorZ: 0,
      maxLength: ARENA_CONFIG.TETHER.INITIAL_LENGTH,
      currentLength: ARENA_CONFIG.TETHER.INITIAL_LENGTH,
      isAttached: true,
      tension: 0.0,
      dynamicVelX: 0.0,
      dynamicVelY: 0.0
    });
    this.healths.add(playerId, { current: GAMEPLAY_TUNING.PLAYER.MAX_INTEGRITY, max: GAMEPLAY_TUNING.PLAYER.MAX_INTEGRITY });
    this.inputs.add(playerId, { x: 0, y: 0, jump: false });
    this.playerTags.add(playerId, {});
    this.traversal.add(playerId, {
      state: "AIRBORNE",
      wallNormalX: 0,
      wallNormalY: 0,
      wallDir: 0,
      launchTimer: 0.0,
      launchPower: 0.0
    });
    this.iframes.add(playerId, { timeRemaining: 0 });
    this.refs.player = playerId;

    const pMesh = BABYLON.MeshBuilder.CreateCapsule(
      "playerVisual",
      { height: ARENA_CONFIG.ENTITY.PLAYER_HEIGHT, radius: ARENA_CONFIG.ENTITY.PLAYER_RADIUS, subdivisions: 3 },
      scene
    );
    const pMat = new BABYLON.PBRMaterial("playerMat", scene);
    pMat.albedoColor = new BABYLON.Color3(0.88, 0.9, 0.92);
    pMat.metallic = VISUAL_JUICE_CONFIG.MATERIALS.PLAYER.METALLIC;
    pMat.roughness = VISUAL_JUICE_CONFIG.MATERIALS.PLAYER.ROUGHNESS;
    pMat.sheen.isEnabled = true;
    pMat.sheen.intensity = VISUAL_JUICE_CONFIG.MATERIALS.PLAYER.SHEEN_INTENSITY;
    pMat.sheen.roughness = VISUAL_JUICE_CONFIG.MATERIALS.PLAYER.SHEEN_ROUGHNESS;
    pMat.sheen.color = new BABYLON.Color3(0.95, 0.95, 1.0);
    pMesh.material = pMat;
    this.visualRegistry.registerTransformNode(playerId, pMesh);

    return playerId;
  }
}

src/gameplay/combat/CombatSystem.ts:
import { ARENA_CONFIG, GAMEPLAY_TUNING } from "../../core/engine/ArenaConfig";
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { ComponentStore } from "../../core/ecs/ComponentStore";
import {
  TransformComponent,
  HealthComponent,
  WeaverAIComponent,
  TetherComponent,
  InvulnerabilityComponent,
  TraversalStateComponent,
  KinematicTargetComponent
} from "../../core/ecs/Components";
import { EntityRefs } from "../../core/ecs/EntityRefs";
import { EventBroker } from "../../core/events/EventBroker";
import { GameEvent } from "../../core/events/GameEvents";
import { CommandBus } from "../../core/commands/CommandBus";

export class CombatSystem implements ISystem {
  readonly phase = SystemPhase.Gameplay;

  private readonly COMBINED_RADIUS_THRESHOLD = ARENA_CONFIG.ENTITY.PLAYER_RADIUS + ARENA_CONFIG.ENTITY.WEAVER_RADIUS;
  private readonly BROADPHASE_ENVELOPE = 
    (ARENA_CONFIG.ENTITY.PLAYER_RADIUS + ARENA_CONFIG.ENTITY.WEAVER_RADIUS + GAMEPLAY_TUNING.COMBAT.BROADPHASE_MARGIN) * 
    (ARENA_CONFIG.ENTITY.PLAYER_RADIUS + ARENA_CONFIG.ENTITY.WEAVER_RADIUS + GAMEPLAY_TUNING.COMBAT.BROADPHASE_MARGIN);

  constructor(
    private refs: EntityRefs,
    private transforms: ComponentStore<TransformComponent>,
    private healths: ComponentStore<HealthComponent>,
    private weaverAIs: ComponentStore<WeaverAIComponent>,
    private tethers: ComponentStore<TetherComponent>,
    private iframes: ComponentStore<InvulnerabilityComponent>,
    private traversal: ComponentStore<TraversalStateComponent>,
    private broker: EventBroker,
    private commands: CommandBus,
    private targets: ComponentStore<KinematicTargetComponent>
  ) {}

  public update(dt: number): void {
    const pHealth = this.healths.get(this.refs.player);
    const wHealth = this.healths.get(this.refs.weaver);
    const wAI = this.weaverAIs.get(this.refs.weaver);
    const pIframe = this.iframes.get(this.refs.player);
    const tether = this.tethers.get(this.refs.player);
    const pTrav = this.traversal.get(this.refs.player);

    if (!pHealth || !wHealth || !wAI || !pIframe || !tether || !pTrav) return;

    if (pHealth.current <= 0 || wHealth.current <= 0) return;

    if (pIframe.timeRemaining > 0) {
      pIframe.timeRemaining -= dt;
    }

    const pTrans = this.transforms.get(this.refs.player);
    const wTrans = this.transforms.get(this.refs.weaver);
    if (!pTrans || !wTrans) return;

    const dx = pTrans.x - wTrans.x;
    const dy = pTrans.y - wTrans.y;
    const distSq = dx * dx + dy * dy;

    if (distSq > this.BROADPHASE_ENVELOPE) {
      return;
    }

    const dist = Math.sqrt(distSq) || 1.0;
    const isColliding = dist < this.COMBINED_RADIUS_THRESHOLD;
    if (!isColliding) return;

    const tuning = GAMEPLAY_TUNING.COMBAT;

    if (pTrav.state === "LAUNCHING" && pTrav.launchPower >= tuning.FLING_DAMAGE_THRESHOLD) {
      this.resolvePlayerFlingHit(wHealth, tether, pTrav, dx, dy, distSq);
      return;
    }

    const weaverIsHostile = wAI.state === "DASHING";

    if (pIframe.timeRemaining <= 0 && weaverIsHostile) {
      this.resolveWeaverContactHit(pHealth, pIframe, dx, dy, distSq);
      return;
    }

    if (dist < this.COMBINED_RADIUS_THRESHOLD) {
      const overlap = this.COMBINED_RADIUS_THRESHOLD - dist;
      const nx = dx / dist;
      const ny = dy / dist;

      const shiftX = nx * overlap;
      const shiftY = ny * overlap;

      pTrans.x += shiftX;
      pTrans.y += shiftY;
      pTrans.prevX += shiftX;
      pTrans.prevY += shiftY;

      const pTarget = this.targets.get(this.refs.player);
      if (pTarget) {
        pTarget.x += shiftX;
        pTarget.y += shiftY;
      }

      const dot = tether.dynamicVelX * nx + tether.dynamicVelY * ny;
      if (dot < 0) {
        tether.dynamicVelX -= dot * nx * tuning.BOUNCE_ELASTICITY_MULT;
        tether.dynamicVelY -= dot * ny * tuning.BOUNCE_ELASTICITY_MULT;
      }
    }
  }

  private resolvePlayerFlingHit(
    wHealth: HealthComponent,
    tether: TetherComponent,
    pTrav: TraversalStateComponent,
    dx: number,
    dy: number,
    distSq: number
  ): void {
    const tuning = GAMEPLAY_TUNING.COMBAT;
    wHealth.current -= tuning.PLAYER_FLING_DAMAGE;

    this.broker.publish(GameEvent.WEAVER_DAMAGED, {
      amount: tuning.PLAYER_FLING_DAMAGE,
      source: "PLAYER_FLING"
    });

    this.broker.publish(GameEvent.WEAVER_HEALTH_CHANGED, {
      hp: Math.max(0, wHealth.current),
      maxHp: wHealth.max
    });

    this.broker.publish(GameEvent.CAMERA_SHAKE_TRIGGERED, { amplitude: 1.4, duration: 0.55 });

    const dist = Math.sqrt(distSq) || 1;
    tether.dynamicVelX = (dx / dist) * tuning.REBOUND_FORCE;
    tether.dynamicVelY = (dy / dist) * tuning.REBOUND_FORCE;
    pTrav.state = "AIRBORNE";
    pTrav.launchPower = 0;
    pTrav.launchTimer = 0;
  }

  private resolveWeaverContactHit(
    pHealth: HealthComponent,
    pIframe: InvulnerabilityComponent,
    dx: number,
    dy: number,
    distSq: number
  ): void {
    const tuning = GAMEPLAY_TUNING.COMBAT;
    pHealth.current -= tuning.WEAVER_CONTACT_DAMAGE;
    pIframe.timeRemaining = tuning.PLAYER_IFRAME_DURATION;

    const dist = Math.sqrt(distSq) || 1;
    this.commands.dispatch({
      type: "APPLY_IMPULSE",
      entityId: this.refs.player,
      x: (dx / dist) * tuning.KNOCKBACK_FORCE_X,
      y: (dy / dist) * tuning.KNOCKBACK_FORCE_Y + tuning.KNOCKBACK_BONUS_Y,
      z: 0
    });

    this.broker.publish(GameEvent.PLAYER_DAMAGED, {
      amount: tuning.WEAVER_CONTACT_DAMAGE,
      source: "WEAVER"
    });
    this.broker.publish(GameEvent.PLAYER_HEALTH_CHANGED, {
      hp: pHealth.current,
      maxHp: pHealth.max
    });
    this.broker.publish(GameEvent.CAMERA_SHAKE_TRIGGERED, { amplitude: 0.5, duration: 0.3 });

    if (pHealth.current <= 0) {
      pHealth.current = 0;
      this.broker.publish(GameEvent.PLAYER_DIED, undefined);
    }
  }
}

