  justify-content: space-between;
  pointer-events: none;
  font-family: "SF Mono", Monaco, Consolas, "Courier New", monospace;
}

.hud-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.hud-bottom {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.hud-panel {
  background: rgba(14, 14, 17, 0.85);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border-subtle);
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 180px;
}

.hud-right {
  align-items: flex-end;
}

.hud-center {
  min-width: 260px;
}

.hud-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--text-muted);
  text-transform: uppercase;
}

.hud-label-row {
  display: flex;
  justify-content: space-between;
  width: 100%;
  align-items: center;
}

.hud-value {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-main);
}

.hud-subtext {
  font-size: 10px;
  color: var(--text-muted);
  letter-spacing: 0.05em;
}

.hud-hp-row {
  display: flex;
  gap: 6px;
}

.hp-block {
  width: 16px;
  height: 8px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-subtle);
  transition: all 0.2s ease;
}

.hp-active {
  background: var(--accent-success);
  border-color: var(--accent-success);
  box-shadow: 0 0 8px rgba(16, 185, 129, 0.4);
}

.hud-bar-track {
  width: 100%;
  height: 6px;
  background: var(--bg-void);
  border: 1px solid var(--border-subtle);
  overflow: hidden;
}

.hud-bar-fill {
  height: 100%;
  width: 100%;
  transform: scaleX(0);
  transform-origin: left;
  background: var(--accent-danger);
  transition:
    transform 0.15s ease,
    background-color 0.15s ease;
}

.hud-state-text {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  margin-top: 4px;
}

.hud-hint {
  font-size: 10px;
  letter-spacing: 0.15em;
  color: var(--text-muted);
  opacity: 0;
  transition: opacity 0.2s ease;
  text-align: center;
  font-weight: 700;
}

.overlay-root {
  position: absolute;
  inset: 0;
  background: rgba(5, 5, 6, 0.92);
  backdrop-filter: blur(12px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 99;
  padding: 24px;
  box-sizing: border-box;
}

.overlay-modal {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 32px;
  border: 1px solid var(--border-strong);
  background: var(--bg-surface);
  max-width: 400px;
  width: 85%;
  box-sizing: border-box;
  text-align: center;
}

.overlay-title {
  font-size: 28px;
  margin: 0;
  letter-spacing: 0.2em;
  font-weight: 900;
  text-transform: uppercase;
}

.overlay-divider {
  height: 2px;
  width: 48px;
  background: var(--border-strong);
  margin: 24px 0;
}

.overlay-subtitle {
  font-size: 12px;
  color: var(--text-muted);
  margin: 0 0 32px 0;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.overlay-btn {
  background: var(--bg-elevated);
  border: 1px solid var(--border-strong);
  color: var(--text-main);
  padding: 14px 32px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.15s ease;
  outline: none;
  pointer-events: auto;
  font-family: inherit;
}

.overlay-btn:hover {
  background: var(--text-main);
  color: var(--bg-void);
  border-color: var(--text-main);
}

.overlay-btn:active {
  transform: scale(0.98);
}

